package operator;

public class Operatorclsswork1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int a = 20;
		int value=a++;
		System.out.println("Value1 ="+value+"\t"+"a = "+a);
		
		int value1=++a;
		System.out.println("Value2 ="+value1+"\t"+"a = "+a);
		
		int value2=a--;
		System.out.println("Value3 ="+value2+"\t"+"a = "+a);

		int value3=--a;
		System.out.println("Value4 ="+value+"\t"+"a = "+a);
	}

}
